<script>
(function(){const f=document.getElementById('appointmentForm'),grid=document.getElementById('calendarDays'),label=document.getElementById('calendarMonth'),prev=document.getElementById('previousMonth'),next=document.getElementById('nextMonth'),dateField=document.getElementById('appointmentDate'),timeField=document.getElementById('appointmentTime'),company=document.getElementById('appointmentCompany'),slots=document.getElementById('timeSlots'),selected=document.getElementById('appointmentSelected'),status=document.getElementById('appointmentStatus'),today=new Date();today.setHours(0,0,0,0);let view=new Date(today.getFullYear(),today.getMonth(),1),chosenDate='',chosenDateLabel='',chosenTime='';const times=['09:00 am','09:30 am','10:00 am','10:30 am','11:00 am','11:30 am','12:00 pm','12:30 pm','01:00 pm','01:30 pm','02:00 pm','02:30 pm','03:00 pm','03:30 pm','04:00 pm','04:30 pm','05:00 pm'];function key(y,m,d){return y+'-'+String(m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0')}function pretty(d){return d.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'})}function draw(){let y=view.getFullYear(),m=view.getMonth(),first=new Date(y,m,1).getDay(),total=new Date(y,m+1,0).getDate();label.textContent=view.toLocaleDateString('en-US',{month:'long',year:'numeric'});prev.disabled=y===today.getFullYear()&&m===today.getMonth();grid.innerHTML='';for(let i=0;i<first;i++)grid.appendChild(document.createElement('span'));for(let d=1;d<=total;d++){let date=new Date(y,m,d),b=document.createElement('button'),k=key(y,m,d);b.type='button';b.textContent=String(d).padStart(2,'0');b.disabled=date<today;if(date.toDateString()===today.toDateString())b.classList.add('today');if(k===chosenDate)b.classList.add('selected');b.onclick=()=>{chosenDate=k;chosenDateLabel=pretty(date);chosenTime='';dateField.value=chosenDate;timeField.value='';draw();drawTimes();copy()};grid.appendChild(b)}}function drawTimes(){if(!chosenDate){slots.innerHTML='<p>Choose a date to view available times.</p>';return}slots.innerHTML=times.map(t=>'<button type="button" class="time-slot '+(t===chosenTime?'selected':'')+'" data-time="'+t+'">'+t+'</button>').join('');slots.querySelectorAll('button').forEach(b=>b.onclick=()=>{chosenTime=b.dataset.time;timeField.value=chosenTime;drawTimes();copy()})}function copy(){selected.textContent=chosenDate&&chosenTime?'Selected: '+chosenDateLabel+' at '+chosenTime+' ET':chosenDate?'Selected: '+chosenDateLabel+' — now choose a time.':'No date or time selected yet.'}prev.onclick=()=>{if(!prev.disabled){view.setMonth(view.getMonth()-1);draw()}};next.onclick=()=>{view.setMonth(view.getMonth()+1);draw()};f.onsubmit=e=>{e.preventDefault();status.className='appointment-status';if(!chosenDate||!chosenTime){status.textContent='Please select an available date and time.';status.classList.add('error');return}if(!f.reportValidity())return;f.querySelector('[name="company_name"]').value=company.value.trim();let b=f.querySelector('button[type="submit"]');b.disabled=true;b.textContent='Sending request…';fetch(f.action,{method:'POST',body:new FormData(f),headers:{Accept:'application/json'}}).then(r=>r.json()).then(data=>{status.textContent=data.message||'Thank you. We will be in touch soon.';status.classList.add(data.status==='success'?'success':'error');if(data.status==='success'){f.reset();chosenDate='';chosenDateLabel='';chosenTime='';dateField.value='';timeField.value='';draw();drawTimes();copy()}}).catch(()=>{status.textContent='We could not send your request. Please email info@empireonecx.com.';status.classList.add('error')}).finally(()=>{b.disabled=false;b.innerHTML='Request my strategy call <i class="fas fa-arrow-right"></i>'})};draw();drawTimes()})();
</script>
